# verify melody notes against underlying chords - flag dissonances
import sys; sys.path.insert(0,'/workspace/src')
import importlib, compose
importlib.reload(compose)
from compose import CH, PROG_A, PROG_B, PROG_C, PROG_E, HOOK1,HOOK2,HOOK3,HOOK4,MEL_A,MEL_A2, scale_note

def check(name, mel, prog):
    bad=[]
    for (r,m,dur) in mel:
        bar = r//16
        cn = prog[bar % len(prog)]
        d = CH[cn]
        pcs = {(d['root']+i)%12 for i in d['ints']}
        # allowed extensions: 9th, 11th on minor, 6th
        ext = {(d['root']+2)%12}
        if d['ints'][1]==3: ext |= {(d['root']+5)%12, (d['root']+10)%12}
        else: ext |= {(d['root']+9)%12, (d['root']+11)%12}
        pc = m%12
        if pc not in pcs and pc not in ext:
            bad.append((r,m,cn,dur))
    print(f'{name:7s} over {prog}: {len(bad)} outside -> {bad}')
check('HOOK1',HOOK1,PROG_B); check('HOOK2',HOOK2,PROG_B)
