import numpy as np, wave

def render_subset(keep, path):
    compose.CELLS.clear(); compose.PATS.clear(); compose.build_patterns()
    order, ls = compose.build_order()
    C, ins = compose.load_calls(compose.NCH,"sub")
    npat=max(compose.PATS)+1
