    for i,p in enumerate(order): C.append({"name":"order_set","arguments":{"position":i,"pattern":p}})
    for (p,r,ch),kw in sorted(compose.CELLS.items()):
        if ch not in keep: continue
        a=dict(pattern=p,row=r,channel=ch); a.update(kw)
        C.append({"name":"pattern_set_cell","arguments":a})
